import{_ as a,o as t,c as o,a4 as s}from"./chunks/framework.YC5CMuPM.js";const u=JSON.parse('{"title":"Tips and tricks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tips-and-tricks.md","filePath":"guide/tips-and-tricks.md","lastUpdated":1790704478000}'),n={name:"guide/tips-and-tricks.md"};function r(i,e,l,d,c,f){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="tips-and-tricks" tabindex="-1">Tips and tricks <a class="header-anchor" href="#tips-and-tricks" aria-label="Permalink to &quot;Tips and tricks&quot;">​</a></h1><p><strong>Practical lessons from working JUCE developers, collected from a community forum thread and the blog post it discusses.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> They cover debugging, GUI performance, plug-in formats, and build settings.</strong></p><p>These notes are paraphrased and grouped by topic. They come from community experience, not from the JUCE team, so check anything that matters against the headers and your own host and platform. The thread continues to grow, so read it for more.</p><h2 id="debugging-and-testing" tabindex="-1">Debugging and testing <a class="header-anchor" href="#debugging-and-testing" aria-label="Permalink to &quot;Debugging and testing&quot;">​</a></h2><ul><li><strong>Log to a file.</strong> Plug-ins run inside hosts where a console is often unavailable. Write diagnostics to disk with <code>FileLogger</code> from <code>juce_core</code>, or with a logging library such as <code>spdlog</code>.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup></li><li><strong>Validate with <code>pluginval</code>.</strong> Run it regularly, and add it to continuous integration so a broken plug-in fails the build.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1:2]</a></sup></li><li><strong>Build with AddressSanitizer (ASAN).</strong> It turns many memory-related crashes into reports that point at the cause.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1:3]</a></sup></li></ul><h2 id="gui-and-performance" tabindex="-1">GUI and performance <a class="header-anchor" href="#gui-and-performance" aria-label="Permalink to &quot;GUI and performance&quot;">​</a></h2><ul><li><strong>Prefer <code>VBlankAttachment</code> to a <code>Timer</code> for animation.</strong> It calls you once per display refresh, so repaints line up with frames.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1:4]</a></sup></li><li><strong>Avoid <code>setBufferedToImage()</code> on a component that has children.</strong> A change in any child invalidates the parent&#39;s cached image. Put the content you want cached in a sibling component instead.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1:5]</a></sup></li><li><strong>Use <code>Label</code> rather than <code>Graphics::drawText()</code> for text.</strong> A <code>Label</code> is a component, so it takes part in JUCE&#39;s accessibility support and is visible to screen readers. Text you paint yourself is not. See the <a href="https://github.com/andrewh/JUCE/blob/master/docs/Accessibility.md" target="_blank" rel="noreferrer">accessibility notes</a> in the repository.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1:6]</a></sup></li></ul><h2 id="talking-between-processor-and-editor" tabindex="-1">Talking between processor and editor <a class="header-anchor" href="#talking-between-processor-and-editor" aria-label="Permalink to &quot;Talking between processor and editor&quot;">​</a></h2><ul><li><strong>Send updates asynchronously.</strong> Use listener-style messaging such as <code>ValueTree::Listener::valueTreePropertyChanged</code> rather than handing the processor a lambda that captures the editor. The editor can be destroyed while the processor lives on, so a stored lambda can outlive what it captures.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1:7]</a></sup></li></ul><h2 id="plug-in-formats-and-hosts" tabindex="-1">Plug-in formats and hosts <a class="header-anchor" href="#plug-in-formats-and-hosts" aria-label="Permalink to &quot;Plug-in formats and hosts&quot;">​</a></h2><ul><li><strong>Set the version to 0 in debug builds for AU.</strong> Hosts then rescan the Audio Unit on each launch instead of caching an old copy.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1:8]</a></sup></li><li><strong>Build and run the app target first for AUv3.</strong> The plug-in extension is packaged inside the app, so the host only sees it once the app has been installed.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1:9]</a></sup></li><li><strong>Link the Windows runtime statically.</strong> This avoids depending on a redistributable being installed on the user&#39;s machine.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1:10]</a></sup></li></ul><h2 id="build-and-code-hygiene" tabindex="-1">Build and code hygiene <a class="header-anchor" href="#build-and-code-hygiene" aria-label="Permalink to &quot;Build and code hygiene&quot;">​</a></h2><ul><li><p><strong>Expose the build configuration to your code.</strong> Multi-config generators such as Xcode and Visual Studio choose the configuration at build time, so use a generator expression:<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1:11]</a></sup></p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-dark tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#F97583;--shiki-dark:#BB9AF7;">target_compile_definitions</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#A9B1D6;">(MyPlugin </span><span style="--shiki-light:#B392F0;--shiki-dark:#A9B1D6;">PRIVATE</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECE6A;"> &quot;BUILD_CONFIG=$&lt;CONFIG&gt;&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div></li><li><p><strong>Format with <code>clang-format</code>.</strong> Automatic formatting keeps diffs small and removes style debates.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1:12]</a></sup></p></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./build-systems.html">Build systems</a>: CMake, the Projucer, and module flags</li><li><a href="./plugin-anatomy.html">Anatomy of a plug-in</a>: processor, editor, and parameters</li><li><a href="./core-concepts.html">Core concepts</a>: ownership, listeners, and state</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://forum.juce.com/t/the-big-list-of-juce-tips-and-tricks-from-n00b-to-pro/62193" target="_blank" rel="noreferrer">&quot;The big list of JUCE tips and tricks, from n00b to pro&quot;</a>, JUCE community forum, and the <a href="https://melatonin.dev/blog/big-list-of-juce-tips-and-tricks/" target="_blank" rel="noreferrer">blog post</a> it links to. Summarised in this site&#39;s own words. Individual contributors are not named here, so follow the thread for original credit and further tips. <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a> <a href="#fnref1:2" class="footnote-backref">↩︎</a> <a href="#fnref1:3" class="footnote-backref">↩︎</a> <a href="#fnref1:4" class="footnote-backref">↩︎</a> <a href="#fnref1:5" class="footnote-backref">↩︎</a> <a href="#fnref1:6" class="footnote-backref">↩︎</a> <a href="#fnref1:7" class="footnote-backref">↩︎</a> <a href="#fnref1:8" class="footnote-backref">↩︎</a> <a href="#fnref1:9" class="footnote-backref">↩︎</a> <a href="#fnref1:10" class="footnote-backref">↩︎</a> <a href="#fnref1:11" class="footnote-backref">↩︎</a> <a href="#fnref1:12" class="footnote-backref">↩︎</a></p></li></ol></section>',18)])])}const p=a(n,[["render",r]]);export{u as __pageData,p as default};
